<?php
 namespace QQWorld\Braintree\Gateway\Request; use QQWorld\Framework\Exception\LocalizedException; use QQWorld\Braintree\Gateway\Helper\SubjectReader; use QQWorld\Payment\Gateway\Request\BuilderInterface; use QQWorld\Payment\Helper\Formatter; class CaptureDataBuilder implements BuilderInterface { use Formatter; const TRANSACTION_ID = 'transaction_id'; private $subjectReader; public function __construct(SubjectReader $subjectReader) { $this->subjectReader = $subjectReader; } public function build(array $buildSubject) { $paymentDO = $this->subjectReader->readPayment($buildSubject); $payment = $paymentDO->getPayment(); $transactionId = $payment->getCcTransId(); if (!$transactionId) { throw new LocalizedException(__('No authorization transaction to proceed capture.')); } return [ self::TRANSACTION_ID => $transactionId, PaymentDataBuilder::AMOUNT => $this->formatPrice($this->subjectReader->readAmount($buildSubject)) ]; } } 